const e = items[0].json;

return [{
  json: {
    workflow_name: e.workflow?.name || 'unknown',
    execution_id: String(e.execution?.id || ''),
    failed_node: e.execution?.lastNodeExecuted || 'unknown',
    error_message: (e.execution?.error?.message || 'no message').slice(0, 2000),
    error_stack: (e.execution?.error?.stack || '').slice(0, 4000),
    payload: JSON.stringify(e).slice(0, 20000)
  }
}];
